import Map from 'ol/Map.js';
import View from 'ol/View.js';
import WMTSCapabilities from 'ol/format/WMTSCapabilities.js';
import TileLayer from 'ol/layer/Tile.js';
import OSM from 'ol/source/OSM.js';
import WMTS, { optionsFromCapabilities } from 'ol/source/WMTS.js';
import './style.css';
import { fromLonLat } from 'ol/proj.js';
import VectorLayer from 'ol/layer/Vector.js';
import VectorSource from 'ol/source/Vector.js';
import GeoJSON from 'ol/format/GeoJSON.js';
import { Stroke, Style } from 'ol/style.js';

// URL du backend local
const BACKEND_URL = 'http://localhost:8000/';

//variables globales
let map; //ol
let layerStats = {}; //stock des stats par nom de couche, ex: { "mon_trajet": { distance_km: 12, d_plus: 300, ... } }
let cumulativeStats = {}; // stock les stats cumulees a afficher dans l'UI
const layerMap = {}; //map des couches visibles sur la carte
let checkedLayers = {}; // etat des checkbox (bool)

//Initialisation du fond de carte (WMTS + OSM) (donné en cours)
fetch('https://wmts.geo.admin.ch/EPSG/3857/1.0.0/WMTSCapabilities.xml?lang=fr')
  .then(response => response.text())
  .then(text => {
    const result  = new WMTSCapabilities().read(text);
    const options = optionsFromCapabilities(result, {
      layer: 'ch.swisstopo.pixelkarte-farbe',
      matrixSet: 'EPSG:2056',
    });

    map = new Map({
      layers: [
        new TileLayer({ source: new OSM(), opacity: 0.3 }),
        new TileLayer({ source: new WMTS(options), opacity: 1 }),
      ],
      target: 'map',
      view: new View({
        center: fromLonLat([8.2275, 46.8182]),
        zoom: 8.25,
        minZoom: 8.25,
        extent: [500000, 5650000, 1300000, 6100000], //etendue de la vue
      }),
    });
  });

// input pour sélectionner des fichiers GPX
const fileInput = document.getElementById('file-input');

//listener sur la selection de fichier, declenche la piple de traitement
fileInput.addEventListener('change', () => {
  handleFiles(fileInput.files);
});

//Pipeline de traitement
// etapes : envoyer les fichiers au backend (upload) -> charger traces -> charger stats -> construire le panneau de layers
function handleFiles(files) {

  const gpxFiles = Array.from(files).filter(f => f.name.endsWith('.gpx'));
  if (gpxFiles.length === 0) return; // sortie si aucun gpx fourni

  //envoi au backend et chainage des promesses .then()
  sendToBackend(gpxFiles)
    .then(() => loadGpsTracks(gpxFiles)) //charger les traces sur l UI
    .then(() => loadStats(gpxFiles)) //charger les stats de la trace
    .then(() => LayerPanel(gpxFiles))//afficher la trace dans le panneau de selection
    .catch(err => console.error('Erreur pipeline :', err));
}

//ENVOI DES FICHIERS AU BACKEND
function sendToBackend(files) {
  const formData = new FormData(); //meme but qu'un objet mais multipart
  for (const file of files) {
    formData.append('gpx_file', file);
  }

  // fetch POST -> /upload-gpx
  return fetch(BACKEND_URL + 'upload-gpx', {
      method: 'POST',
      credentials: 'include',
      body: formData
  }) //nom de la route
  .then(response => {
    if (!response.ok) throw new Error('Erreur upload : ' + response.status);
    console.log('Fichiers envoyés avec succès.');
  });
}


const COLORS = ['#ff0000', '#00ff00', '#0000ff', '#ff00ff'];

//CHARGEMENT DES TRACES DEPUIS LE BACKEND
function loadGpsTracks(gpxFiles) {
  const url = BACKEND_URL + 'download-geojson'; //nom de la route

  return fetch(url, { method: 'POST', credentials: 'include' })
    .then(response => {
      if (!response.ok) throw new Error('Erreur GeoJSON : ' + response.status);
      return response.json();
    })
    .then(geojson => {
      // Normalisations pour avoir une FeatureCollection
      if (geojson.type === 'Feature') {
        geojson = { type: 'FeatureCollection', features: [geojson] };
      } else if (geojson.type !== 'FeatureCollection') {
        geojson = { type: 'FeatureCollection', features: [{ type: 'Feature', geometry: geojson, properties: {} }] };
      }

      const fileName = gpxFiles[0].name.replace('.gpx', '');

      //creation de la source vectorielle
      const vectorSource = new VectorSource({
        features: new GeoJSON().readFeatures(geojson, {
          featureProjection: 'EPSG:3857', // projection de la carte (pseudo mercator)
          dataProjection: 'EPSG:4326',    // projection des données GeoJSON (WGS 84)
        }),
      });

      //creation de la couche vectorielle
      const vectorLayer = new VectorLayer({
        source: vectorSource,
        style: (feature) => new Style({
          stroke: new Stroke({
            color: COLORS[(feature.get('id') || 0) % COLORS.length],
            width: 3,
          }),
        }),
      });

      // Enregistrer la couche dans layerMap pour y acceder plus tard via son nom
      layerMap[fileName] = vectorLayer;
      // Ajouter la couche a la carte pour l'afficher
      map.addLayer(vectorLayer);
    });
}

//CHARGEMENT DES STATS
function loadStats(files) {
  const formData = new FormData();
  for (const file of files) {
    formData.append('gpx_file', file);
  }

  return fetch(BACKEND_URL + 'stats', { method: 'POST', body: formData })
    .then(response => {
      if (!response.ok) throw new Error('Erreur stats : ' + response.status);
      return response.json();
    })
    .then(stats => {

      const fileName = files[0].name.replace('.gpx', '');

      //chekcbox cochee par défaut pour la couche
      checkedLayers[fileName] = true;

      // Stocker les stats dans layerStats
      layerStats[fileName] = {
          distance_km: stats.distance_km,
          d_plus: stats.d_plus,
          equi_UTMB: stats.equi_UTMB,
          equi_DiagFou: stats.equi_DiagFou,
          equi_Marathon: stats.equi_Marathon,
          equi_SwissMan: stats.equi_SwissMan,
          equi_ultraTerrestre: stats.equi_ultraTerrestre,
      };
      //recalculer les stats, voir ligne 174
      recomputeStats();
    });
}

// recalculer les stats cumulees en fonction de ce qui est coché
function recomputeStats() {

    cumulativeStats = {
        distance_km : 0,
        d_plus : 0,
        equi_UTMB : 0,
        equi_DiagFou : 0,
        equi_Marathon : 0,
        equi_SwissMan : 0,
        equi_ultraTerrestre : 0,
    };

    for (const [fileName, isChecked] of Object.entries(checkedLayers)){
        //si la couche est cochee on ajout les stats a cumulativeStats
        if (isChecked === true && layerStats[fileName]) {
            cumulativeStats.distance_km += layerStats[fileName].distance_km;
            cumulativeStats.d_plus += layerStats[fileName].d_plus;
            cumulativeStats.equi_UTMB += layerStats[fileName].equi_UTMB;
            cumulativeStats.equi_DiagFou += layerStats[fileName].equi_DiagFou;
            cumulativeStats.equi_Marathon += layerStats[fileName].equi_Marathon;
            cumulativeStats.equi_SwissMan += layerStats[fileName].equi_SwissMan;
            cumulativeStats.equi_ultraTerrestre += layerStats[fileName].equi_ultraTerrestre;
        }
    }

    // Mise à jour de l'UI
    document.getElementById('dist').textContent   = 'Distance : ' + cumulativeStats.distance_km.toFixed(2) + ' km';
    document.getElementById('d_plus').textContent = 'D+ : '       + cumulativeStats.d_plus + ' m';

    updateComparateurDisplay();
}

//COMPARATEUR DE COURSES
function updateComparateurDisplay() {
  const choix = document.getElementById('comparateur_courses').value;

  const textes = {
    DiagFou:  'Equivalent Diagonale des fous : ' + (cumulativeStats.equi_DiagFou).toFixed(2)  + ' x fois',
    UTMB:     'Equivalent UTMB : '               + (cumulativeStats.equi_UTMB).toFixed(2)     + ' x fois',
    Marathon: 'Equivalent Marathon : '           + (cumulativeStats.equi_Marathon).toFixed(2) + ' x fois',
    SwissMan: 'Equivalent SwissMan : '           + (cumulativeStats.equi_SwissMan).toFixed(2) + ' x fois',
    UltraTerrestre: 'Equivalent Ultra Terrestre : ' + (cumulativeStats.equi_ultraTerrestre).toFixed(2)  + ' x fois',
  };

  document.getElementById('resulats_comparaison').textContent =
    textes[choix] ?? 'Veuillez sélectionner une course';
}


document.getElementById('comparateur_courses').addEventListener('change', updateComparateurDisplay);

//PANEL DE SELECTION DES COUCHES
function LayerPanel(files){
    const panel = document.getElementById("checkboxes");

    for (const file of files) {
        const fileName = file.name.replace('.gpx', '');

        checkedLayers[fileName] = true;

        //DOM
        const list = document.createElement('li');
        const checkbox = document.createElement("input");
        checkbox.type    = "checkbox";
        checkbox.id      = "checkbox-" + fileName;
        checkbox.name    = fileName;
        checkbox.value   = fileName;
        checkbox.checked = true;

        //listener sur le changement de checkbox
        checkbox.addEventListener('change', (ev) => {
            const layer = layerMap[fileName]; // retrouver la couche par son nom
            if (layer) {

                layer.setVisible(ev.target.checked);
                checkedLayers[fileName] = ev.target.checked;
            } else {

                checkedLayers[fileName] = false;

            }
            //on recalcul les stats en fonction de ce qui est coche
            recomputeStats();
        });

        const checkboxLabel = document.createElement("label");
        checkboxLabel.htmlFor     = "checkbox-" + fileName;
        checkboxLabel.textContent = fileName;

        //ajouter les elements au panel
        panel.appendChild(list);
        panel.appendChild(checkbox);
        panel.appendChild(checkboxLabel);
    }
}